// doc-viewer: 기호 글꼴(Symbol·Wingdings) 글자를 일반 유니코드 글자로 바꾼다.
// Word는 기호 글꼴 글자를 U+F020~U+F0FF(사용자 정의 영역)로 저장한다. 휴대폰에는 이 글꼴이 없어
// 그대로 두면 네모(□)나 빈칸으로 보이므로, 자주 쓰는 글머리 기호·그리스 문자·수학 기호를 바꿔 준다.

// Adobe Symbol 인코딩 0x20~0xFE → 유니코드(0x20~0x3F, 0x5B~0x5F 등 ASCII와 같은 자리는 생략)
const SYMBOL: Record<number, string> = {
  0x22: '∀', 0x24: '∃', 0x27: '∋', 0x2a: '∗', 0x2d: '−', 0x40: '≅',
  0x41: 'Α', 0x42: 'Β', 0x43: 'Χ', 0x44: 'Δ', 0x45: 'Ε', 0x46: 'Φ', 0x47: 'Γ',
  0x48: 'Η', 0x49: 'Ι', 0x4a: 'ϑ', 0x4b: 'Κ', 0x4c: 'Λ', 0x4d: 'Μ', 0x4e: 'Ν',
  0x4f: 'Ο', 0x50: 'Π', 0x51: 'Θ', 0x52: 'Ρ', 0x53: 'Σ', 0x54: 'Τ', 0x55: 'Υ',
  0x56: 'ς', 0x57: 'Ω', 0x58: 'Ξ', 0x59: 'Ψ', 0x5a: 'Ζ', 0x5c: '∴', 0x5e: '⊥',
  0x60: '‾', 0x61: 'α', 0x62: 'β', 0x63: 'χ', 0x64: 'δ', 0x65: 'ε', 0x66: 'φ',
  0x67: 'γ', 0x68: 'η', 0x69: 'ι', 0x6a: 'ϕ', 0x6b: 'κ', 0x6c: 'λ', 0x6d: 'μ',
  0x6e: 'ν', 0x6f: 'ο', 0x70: 'π', 0x71: 'θ', 0x72: 'ρ', 0x73: 'σ', 0x74: 'τ',
  0x75: 'υ', 0x76: 'ϖ', 0x77: 'ω', 0x78: 'ξ', 0x79: 'ψ', 0x7a: 'ζ', 0x7e: '∼',
  0xa0: '€', 0xa1: 'ϒ', 0xa2: '′', 0xa3: '≤', 0xa4: '⁄', 0xa5: '∞', 0xa6: 'ƒ',
  0xa7: '♣', 0xa8: '♦', 0xa9: '♥', 0xaa: '♠', 0xab: '↔', 0xac: '←', 0xad: '↑',
  0xae: '→', 0xaf: '↓', 0xb0: '°', 0xb1: '±', 0xb2: '″', 0xb3: '≥', 0xb4: '×',
  0xb5: '∝', 0xb6: '∂', 0xb7: '•', 0xb8: '÷', 0xb9: '≠', 0xba: '≡', 0xbb: '≈',
  0xbc: '…', 0xbd: '⏐', 0xbe: '⎯', 0xbf: '↵', 0xc0: 'ℵ', 0xc1: 'ℑ', 0xc2: 'ℜ',
  0xc3: '℘', 0xc4: '⊗', 0xc5: '⊕', 0xc6: '∅', 0xc7: '∩', 0xc8: '∪', 0xc9: '⊃',
  0xca: '⊇', 0xcb: '⊄', 0xcc: '⊂', 0xcd: '⊆', 0xce: '∈', 0xcf: '∉', 0xd0: '∠',
  0xd1: '∇', 0xd2: '®', 0xd3: '©', 0xd4: '™', 0xd5: '∏', 0xd6: '√', 0xd7: '⋅',
  0xd8: '¬', 0xd9: '∧', 0xda: '∨', 0xdb: '⇔', 0xdc: '⇐', 0xdd: '⇑', 0xde: '⇒',
  0xdf: '⇓', 0xe0: '◊', 0xe1: '〈', 0xe2: '®', 0xe3: '©', 0xe4: '™', 0xe5: '∑',
  0xe6: '⎛', 0xe7: '⎜', 0xe8: '⎝', 0xe9: '⎡', 0xea: '⎢', 0xeb: '⎣', 0xec: '⎧',
  0xed: '⎨', 0xee: '⎩', 0xef: '⎪', 0xf1: '〉', 0xf2: '∫', 0xf3: '⌠', 0xf4: '⎮',
  0xf5: '⌡', 0xf6: '⎞', 0xf7: '⎟', 0xf8: '⎠', 0xf9: '⎤', 0xfa: '⎥', 0xfb: '⎦',
  0xfc: '⎫', 0xfd: '⎬', 0xfe: '⎭',
};

// Wingdings에서 글머리 기호·체크 표시로 자주 쓰는 것
const WINGDINGS: Record<number, string> = {
  0x21: '✏', 0x22: '✂', 0x28: '☎', 0x2a: '✉', 0x3f: '✍', 0x41: '✌', 0x46: '☞',
  0x4a: '☺', 0x4c: '☹', 0x6c: '●', 0x6d: '❍', 0x6e: '■', 0x6f: '□', 0x70: '◻',
  0x71: '❑', 0x72: '❒', 0x73: '⬧', 0x74: '⧫', 0x75: '◆', 0x76: '❖', 0x77: '⬥',
  0x78: '⌧', 0x9e: '·', 0x9f: '•', 0xa1: '○', 0xa7: '▪', 0xa8: '◻', 0xd8: '➢',
  0xe8: '➔', 0xf0: '⇨', 0xfb: '✗', 0xfc: '✓', 0xfd: '☒', 0xfe: '☑',
};

function tableFor(fontFamily: string | undefined): Record<number, string> {
  const name = (fontFamily || '').toLowerCase();
  if (name.startsWith('wingdings')) return WINGDINGS;
  return SYMBOL;
}

/** U+F020~U+F0FF 글자를 바꾼다. 표에 없으면 bulletFallback(글머리 기호용)이나 원래 글자를 둔다. */
export function mapSymbolText(text: string, fontFamily: string | undefined, bulletFallback = false): string {
  if (!/[-]/.test(text)) return text;
  const table = tableFor(fontFamily);
  let out = '';
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    if (code >= 0xf020 && code <= 0xf0ff) {
      const low = code - 0xf000;
      const mapped = table[low] ?? (table === SYMBOL && low < 0x80 ? String.fromCharCode(low) : undefined);
      out += mapped ?? (bulletFallback ? '•' : ch);
    } else {
      out += ch;
    }
  }
  return out;
}

export function isSymbolFont(fontFamily: string | undefined): boolean {
  const name = (fontFamily || '').toLowerCase();
  return name === 'symbol' || name.startsWith('wingdings') || name === 'webdings';
}
